<?php require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST')exit('Invalid');check_csrf();$id=(int)($_POST['feature_id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$body=trim($_POST['body']??'');if(!$id||!$name||!$body||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Please complete the comment form.');header('Location:index.php');exit;}$s=db()->prepare('INSERT INTO comments(feature_id,name,email,body) VALUES(?,?,?,?)');$s->execute([$id,$name,$email,$body]);$q=db()->prepare('SELECT slug FROM features WHERE id=?');$q->execute([$id]);header('Location:feature.php?slug='.urlencode($q->fetchColumn()));
